(7486568, 1191721, 182284, '<td valign="top">Nice B&amp;W with puppy looking down the stairs which appears to be looking for something, possibly leftovers. I love the contrast of the clouds and the stair rails that really captures your eyes first then to the Left out dog. Nice story in this photo.</td>', 'Nice B&W with puppy looking down the stairs which appears to be looking for something, possibly leftovers. I love the contrast of the clouds and the stair rails that really captures your eyes first then to the Left out dog. Nice story in this photo.', '2016-12-09 02:09:18.000000', NULL, 1),
(7486600, 1191710, 150202, '<td valign="top">While the animal is beautiful I would have loved to see the focus more on the prey. At first glance it just looks like its nose is behind a branch. Moving this shot to the left would have drawn me in more. Still an incredible shot though!</td>', 'While the animal is beautiful I would have loved to see the focus more on the prey. At first glance it just looks like its nose is behind a branch. Moving this shot to the left would have drawn me in more. Still an incredible shot though!', '2016-12-09 06:59:05.000000', NULL, 1),
(7486601, 1191732, 150202, '<td valign="top">I really like the composition and colors, but the background distracts me slightly. Overall good shot.</td>', 'I really like the composition and colors, but the background distracts me slightly. Overall good shot.', '2016-12-09 07:01:10.000000', NULL, 1),
(7486603, 1191497, 150202, '<td valign="top">The subject is nice and crisp while the background is beautifully blurred. Something about this pulls me in. Love it!</td>', 'The subject is nice and crisp while the background is beautifully blurred. Something about this pulls me in. Love it!', '2016-12-09 07:02:33.000000', NULL, 1),
(7486606, 1191752, 150202, '<td valign="top">It''s a beautiful shot, however it looks staged, which doesn''t work for me when the shot is trying to convey the disheveled end of a night.</td>', 'It''s a beautiful shot, however it looks staged, which doesn''t work for me when the shot is trying to convey the disheveled end of a night.', '2016-12-09 07:05:57.000000', NULL, 1),
